{"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立世界观（公寓、信件规则）、引入主角（沈念）、引入核心冲突（预言vs自由意志）",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "第一封信",
        "core_event": "沈念收到第一封信，邮戳日期是三年后，信上只有一句话'不要爱上那个男人'。她开始观察公寓里的邮箱，发现每天都会收到一封信，邮戳日期一天比一天近。",
        "emotional_tone": "悬疑、好奇、不安",
        "key_scenes": [
          "沈念在公寓门口发现第一封信",
          "她观察邮箱，发现信件的规律",
          "她开始怀疑信件的来源"
        ]
      },
      {
        "chapter_number": 2,
        "chapter_title": "验证",
        "core_event": "沈念决定验证信的真假，她故意接近'那个男人'——新搬来的邻居程言。她发现程言温和善良，与她预想的不同。",
        "emotional_tone": "试探、好奇、意外",
        "key_scenes": [
          "沈念在电梯里'偶遇'程言",
          "她故意制造接触机会",
          "她发现程言并不像预言中那样危险"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "倒计时",
        "core_event": "邮戳日期越来越近，从三年后变成一年后，再变成一个月后。沈念开始感到恐慌，她试图疏远程言，但程言却主动接近她。",
        "emotional_tone": "恐慌、抗拒、矛盾",
        "key_scenes": [
          "沈念发现邮戳日期加速倒计时",
          "她试图躲避程言",
          "程言主动敲门，送她亲手做的点心"
        ]
      }
    ],
    "turning_point": "沈念发现邮戳日期已经变成'明天'，她意识到预言即将实现，她必须在今晚做出选择。"
  },
  "act_two": {
    "description": "冲突升级（预言逼近→爱上他→内心挣扎）、沈念陷入困境（爱vs杀）",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "沉溺",
        "core_event": "沈念在与程言的相处中，逐渐放下戒备，她发现自己真的爱上了他。她开始质疑预言的真实性，试图相信命运可以被改变。",
        "emotional_tone": "甜蜜、希望、挣扎",
        "key_scenes": [
          "程言带沈念去看他设计的建筑",
          "两人在公寓楼顶看夜景，程言表白",
          "沈念内心挣扎：她爱他，但预言说她会杀他"
        ]
      },
      {
        "chapter_number": 5,
        "chapter_title": "绝望",
        "core_event": "邮戳日期变成'今天'，沈念收到最后一封信，信上依然是'不要爱上那个男人'，但这次她发现信纸上有血迹。她意识到预言已经实现，她就是凶手。",
        "emotional_tone": "绝望、崩溃、疯狂",
        "key_scenes": [
          "沈念收到今天的信，发现血迹",
          "她回忆起之前的信件，发现每一封信都是她自己写的",
          "她意识到自己就是预言的创造者和执行者"
        ]
      },
      {
        "chapter_number": 6,
        "chapter_title": "选择",
        "core_event": "沈念陷入疯狂，她认为'为了不失去你，我必须在你离开前杀死你'。她开始准备杀人的工具，同时与程言度过最后的时光。",
        "emotional_tone": "疯狂、绝望、深情",
        "key_scenes": [
          "沈念在厨房准备刀具",
          "她与程言共进晚餐，表现得异常温柔",
          "程言告诉她，他明天要出差，可能要离开一段时间"
        ]
      }
    ],
    "turning_point": "程言告诉沈念他要离开，沈念认为这是预言的实现——他会离开她，于是她决定在今晚杀死他，'为了不失去你'。"
  },
  "act_three": {
    "description": "高潮（杀人）+结局（写信），X-Y化学反应爆发（规则怪谈×失去所爱=悲剧必然性）",
    "key_chapters": [
      {
        "chapter_number": 7,
        "chapter_title": "预言",
        "core_event": "沈念在程言离开前，亲手杀死了他。她在杀死他之后，写下了第一封信'不要爱上那个男人'，并将信投入邮箱。她意识到，她收到的所有信，都是她自己写的。",
        "emotional_tone": "悲剧、疯狂、宿命",
        "key_scenes": [
          "沈念在公寓里杀死程言",
          "她在程言死后写下第一封信",
          "她将信投入邮箱，完成时间循环"
        ]
      },
      {
        "chapter_number": 8,
        "chapter_title": "循环",
        "core_event": "沈念坐在公寓里，等待明天的自己收到这封信。她知道，三年前的自己会收到这封信，然后开始验证，然后爱上他，然后杀死他，然后写信。这是一个无法逃脱的循环。",
        "emotional_tone": "绝望、宿命、余韵",
        "key_scenes": [
          "沈念看着邮箱，等待明天的到来",
          "她回忆起与程言的点点滴滴",
          "她意识到，她永远无法逃脱这个循环"
        ]
      }
    ],
    "turning_point": "沈念完成写信，时间循环闭合，她将永远重复这个悲剧。"
  }
}"}

